.result-item__label {
  font-size: .8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .06em;
  margin-bottom: .25rem;
  display: flex;
  align-items: center;
  gap: .35rem;
}
.result-item__label.correct { color: var(--color-correct); }
.result-item__label.incorrect { color: var(--color-incorrect); }
.result-item__label.partial { color: var(--color-skipped); }

.result-item__question { font-size: .95rem; font-weight: 600; margin-bottom: .35rem; }
.result-item__detail { font-size: .85rem; color: var(--color-text-muted); }
.result-item__detail span { font-weight: 600; color: var(--color-text); }

#retry-btn {
  margin-top: 1.25rem;
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  background: transparent;
  color: var(--color-primary);
  border: 1.5px solid var(--color-primary);
  border-radius: var(--radius-btn);
  padding: .65rem 1.5rem;
  font-size: .95rem;
  font-weight: 700;
  cursor: pointer;
  transition: background var(--transition), color var(--transition);
}
#retry-btn:hover { background: #eef0fd; }
#retry-btn:focus-visible { outline: 3px solid var(--color-border-focus); outline-offset: 3px; }

