function ResultItem({ question, selected }) {
  const isCorrect  = setsEqual(question.correct, selected);
  const isPartial  = !isCorrect && setsIntersect(question.correct, selected);
  const isWrong    = !isCorrect && !isPartial;

  const statusKey  = isCorrect ? "correct" : isPartial ? "partial" : "incorrect";
  const statusText = isCorrect ? "Correct" : isPartial ? "Partially correct" : "Incorrect";
  const statusIcon = isCorrect ? SVG.correct : isPartial ? SVG.partial : SVG.wrong;

  const correctLabels = [...question.correct]
    .map(v => question.choices.find(c => c.value === v)?.label ?? v)
    .join(", ");

  const selectedLabels = selected.size > 0
    ? [...selected].map(v => question.choices.find(c => c.value === v)?.label ?? v).join(", ")
    : "None selected";

  const labelEl = el("p", { className: `result-item__label ${statusKey}` },
    icon(statusIcon, { size: 14 }),
    statusText
  );
  const qEl = el("p", { className: "result-item__question" }, question.text);
  const detail = el("p", { className: "result-item__detail" },
    "Your answer: ", el("span", {}, selectedLabels),
    el("br"),
    "Correct answer" + (question.correct.size > 1 ? "s" : "") + ": ", el("span", {}, correctLabels)
  );

  const item = el("div", { className: "result-item" });
  item.append(labelEl, qEl, detail);
  return item;
}

