+    el("span", {}, choice.label)
+  );
+
+  return el("li", {}, label);
+}
+
+/** HelpText — renders help text below the legend */
+function HelpText({ text, id }) {
+  return el("p", { className: "help-text", id },
+    icon(SVG.info, { size: 14 }),
+    text
+  );
+}
+
+/** QuestionCard — wraps a question in .form-field */
+function QuestionCard({ question }) {
+  const helpId = `${question.id}-help`;
+
+  const metaDiv = el("div", { className: "question-meta" });
+  const numberEl = el("p", { className: "question-number" }, question.number);
+  const legend = el("legend", {}, question.text);
+  metaDiv.append(numberEl, legend);
+  if (question.helpText) {
+    metaDiv.append(HelpText({ text: question.helpText, id: helpId }));
+  }
