+/** ResultsPanel — full results section */
+function ResultsPanel({ questions, answers }) {
+  const total = questions.length;
+  const correct = questions.filter(q => setsEqual(q.correct, answers.get(q.id) ?? new Set())).length;
+
+  const badgeClass = correct === total ? "perfect" : correct >= Math.ceil(total / 2) ? "good" : "low";
+  const badgeText  = `${correct} / ${total}`;
+
+  const heading = el("p", { className: "results-heading" },
+    "Your Results ",
+    el("span", { className: `score-badge ${badgeClass}` }, badgeText)
